 r.misc=g("misc");r.mkt=g("mkt");r.listComm=arv*g("listComm")/100;r.sellComm=arv*g("sellComm")/100;r.sellClose=arv*g("sellClose")/100;
 r.credits=g("credits");r.sellMisc=g("sellMisc");
 r.buying=r.points+r.taxCredit+r.buyClose+r.buyComm;r.holding=r.int+r.rehabInt+r.tax+r.ins+r.misc+r.mkt;
 r.selling=r.listComm+r.sellComm+r.sellClose+r.credits+r.sellMisc;r.project=price+r.buying+rep+r.holding;r.net=arv-r.project-r.selling;
